class Solution {
  public List<String> generateParenthesis(int n) {
    List<String> answer = new ArrayList<>();
    Deque<State> stack = new ArrayDeque<>();
    stack.push(new State("", 0, 0));
    while (!stack.isEmpty()) {
      State state = stack.pop();
      if (state.value.length() == 2 * n) { answer.add(state.value); continue; }
      if (state.close < state.open) stack.push(new State(state.value + ")", state.open, state.close + 1));
      if (state.open < n) stack.push(new State(state.value + "(", state.open + 1, state.close));
    }
    return answer;
  }

  private static class State {
    String value; int open, close;
    State(String value, int open, int close) { this.value = value; this.open = open; this.close = close; }
