import java.util.*;

class Solution {
  private static final int[][] DIRS = {{1,0},{-1,0},{0,1},{0,-1}};

  public boolean exist(char[][] board, String word) {
    int rows = board.length, cols = board[0].length;
    for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) {
      if (board[r][c] != word.charAt(0)) continue;
      Deque<State> stack = new ArrayDeque<>();
      stack.push(new State(r, c, 0, new boolean[rows][cols]));
      while (!stack.isEmpty()) {
        State cur = stack.pop();
        if (cur.row < 0 || cur.col < 0 || cur.row == rows || cur.col == cols) continue;
        if (cur.used[cur.row][cur.col] || board[cur.row][cur.col] != word.charAt(cur.index)) continue;
        if (cur.index == word.length() - 1) return true;
        cur.used[cur.row][cur.col] = true;
        for (int[] d : DIRS) stack.push(new State(cur.row + d[0], cur.col + d[1], cur.index + 1, copy(cur.used)));
      }
    }
    return false;
  }

  private boolean[][] copy(boolean[][] used) {
    boolean[][] next = new boolean[used.length][used[0].length];
    for (int i = 0; i < used.length; i++) next[i] = used[i].clone();
    return next;
  }

  private static class State { int row, col, index; boolean[][] used; State(int r,int c,int i,boolean[][] u){row=r;col=c;index=i;used=u;} }
}

