class Solution {
  public boolean exist(char[][] board, String word) {
    for (int r = 0; r < board.length; r++) {
      for (int c = 0; c < board[0].length; c++) {
        if (backtrack(board, word, r, c, 0)) return true;
      }
    }
    return false;
  }

  private boolean backtrack(char[][] board, String word, int r, int c, int index) {
    if (index == word.length()) return true;
    if (r < 0 || c < 0 || r == board.length || c == board[0].length) return false;
    if (board[r][c] != word.charAt(index)) return false;
    char saved = board[r][c];
    board[r][c] = '#';
    boolean found = backtrack(board, word, r + 1, c, index + 1) || backtrack(board, word, r - 1, c, index + 1)
        || backtrack(board, word, r, c + 1, index + 1) || backtrack(board, word, r, c - 1, index + 1);
    board[r][c] = saved;
    return found;
  }
}

