class Solution {
  public List<List<String>> solveNQueens(int n) {
    List<List<String>> answer = new ArrayList<>();
    Deque<State> stack = new ArrayDeque<>();
    stack.push(new State(0, new int[n], new boolean[n], new boolean[2*n], new boolean[2*n]));
    while (!stack.isEmpty()) {
      State s = stack.pop();
      if (s.row == n) { answer.add(build(s.cols)); continue; }
      for (int col = n - 1; col >= 0; col--) {
        int d1 = s.row - col + n, d2 = s.row + col;
        if (s.used[col] || s.d1[d1] || s.d2[d2]) continue;
        State next = s.copy();
        next.cols[s.row] = col;
        next.used[col] = next.d1[d1] = next.d2[d2] = true;
        next.row++;
        stack.push(next);
      }
    }
    return answer;
  }

  private List<String> build(int[] cols) {
    List<String> board = new ArrayList<>();
    for (int col : cols) { char[] row = new char[cols.length]; Arrays.fill(row, '.'); row[col] = 'Q'; board.add(new String(row)); }
    return board;
  }

  private static class State {
    int row; int[] cols; boolean[] used, d1, d2;
    State(int row,int[] cols,boolean[] used,boolean[] d1,boolean[] d2){this.row=row;this.cols=cols;this.used=used;this.d1=d1;this.d2=d2;}
    State copy(){return new State(row, cols.clone(), used.clone(), d1.clone(), d2.clone());}
  }
}

