    Arrays.fill(memo, -1);
    return backtrack(n, 1, 0, memo);
  }

  private int backtrack(int n, int position, int mask, int[] memo) {
    if (position > n) return 1;
    if (memo[mask] != -1) return memo[mask];
    int count = 0;
    for (int num = 1; num <= n; num++) {
      int bit = 1 << (num - 1);
      if ((mask & bit) != 0) continue;
